text:
Here's your water tracker. Tap + for each glass, and it saves the count for today on this device if your app allows it.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:Segoe UI,sans-serif;margin:0;padding:24px;text-align:center;background:#f2f8fc;color:#12324a}
  h1{font-size:20px;margin:0 0 4px}
  .date{font-size:13px;color:#5b7a90;margin-bottom:16px}
  .count{font-size:44px;font-weight:600;margin:8px 0}
  .glasses{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;margin:16px auto;max-width:320px}
  .g{width:56px;height:64px;border-radius:6px 6px 14px 14px;border:2px solid #4a9bd1;background:#fff}
  .g.full{background:#4a9bd1}
  button{font-size:18px;padding:10px 22px;margin:4px;border-radius:8px;border:none;background:#2b7bb9;color:#fff;cursor:pointer}
  button.alt{background:#c9d9e6;color:#12324a}
  .msg{height:24px;font-size:14px;color:#2b7bb9}
</style>
</head>
<body>
  <h1>Water today</h1>
  <div class="date" id="date"></div>
  <div class="count"><span id="n">0</span> / 8</div>
  <div class="glasses" id="glasses"></div>
  <div class="msg" id="msg"></div>
  <button id="plus">+ Add a glass</button>
  <button class="alt" id="minus">- Remove</button>
  <button class="alt" id="reset">Reset</button>
<script>
  var GOAL = 8;
  var today = new Date();
  var key = "water-" + today.toISOString().slice(0,10);
  var count = 0;
  try { count = parseInt(localStorage.getItem(key) || "0", 10) || 0; } catch(e) {}
  document.getElementById("date").textContent = today.toDateString();
  function save(){ try { localStorage.setItem(key, String(count)); } catch(e) {} }
  function draw(){
    document.getElementById("n").textContent = count;
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    for (var i = 0; i < GOAL; i++) {
      var d = document.createElement("div");
      d.className = "g" + (i < count ? " full" : "");
      box.appendChild(d);
    }
    document.getElementById("msg").textContent =
      count >= GOAL ? "Goal reached. Well done!" : (GOAL - count) + " to go";
  }
  document.getElementById("plus").onclick = function(){ count++; save(); draw(); };
  document.getElementById("minus").onclick = function(){ if (count > 0) count--; save(); draw(); };
  document.getElementById("reset").onclick = function(){ count = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```
